missing_calls.command:
/opt/conda/bin/python --version; /opt/conda/bin/python -m pytest --version || true; /opt/conda/bin/python - <<'PY'
mods=['numpy','scipy','networkx','autograd','semantic_version','toml','appdirs']
for m in mods:
 try:
  x=__import__(m); print(m, getattr(x,'__version__','ok'))
 except Exception as e: print(m, type(e).__name__, e)
PY

/opt/conda/bin/python -V; /opt/conda/bin/python -m pytest --version || true; /opt/conda/bin/python - <<'PY'
mods=['numpy','scipy','autograd','autoray','networkx','semantic_version','cachetools','toml','appdirs']
for mod in mods:
    try:
        m=__import__(mod)
        print(mod, getattr(m, '__version__', 'installed'))
    except Exception as e:
        print(mod, 'MISSING', e)
PY

grep -n -E '^_{3,}|^FAILED |^E   |^=+ FAILURES' /tmp/full-pytest.log | head -n 240; /opt/conda/envs/testbed/bin/python - <<'PY'
mods=['torch','jax','jaxlib','tensorflow']
for name in mods:
 try:
  m=__import__(name); print(name, m.__version__)
 except Exception as e: print(name, type(e).__name__, e)
PY
