ls -l /opt/conda/envs/testbed/bin/python* /opt/conda/envs/testbed/bin/pip* 2>/dev/null || true; /opt/conda/envs/testbed/bin/python --version; /opt/conda/envs/testbed/bin/python - <<'PY'
